  logs:{"parses": [{"d": "Kings' Rest +6", "p": 7, "info": "Damage · 36.7K DPS · about 90,092 of 96,874 tanks · timed in 20:24", "date": "7 Oct"}], "best": {"p": 7, "sub": "Kings' Rest +6 · 7 Oct"}, "highest": {"p": 7, "sub": "Kings' Rest +6 · 7 Oct"}, "notesTitle": "What we learned", "notes": [{"date": "7 Oct", "items": ["You didn't take any avoidable damage at all, you held King Dazar for the whole last fight, and you used your defensives a lot, even more than the top-ranked tank.", "The one thing that would make the biggest difference is pressing your buttons a bit more often. That's exactly what Sàm and Ràchel noticed in their logs too, so it's really common.", "The top tanks are almost always casting something, especially Avenger's Shield and Shield of the Righteous. Use those as soon as they're ready and your damage, threat and survivability all go up together.", "It's also worth using Rebuke whenever it's ready on mobs that are casting.", "Consecration: you cast it about twice as often as the top tank. Recast it only when you've moved out of it and use those extra presses on the buttons above."]}], "average": null, "comparisons": [{"kind": "pair", "title": "Kings' Rest +6 · 7 Oct", "sub": "Casts: Dad vs Aquera (#1 tank)", "cols": ["Dad", "Aquera"], "facts": [], "rows": [["Casts per minute", "38.5", "58"], ["Shield of the Righteous", "154", "303"], ["Avenger's Shield", "44", "106"], ["Blessed Hammer", "103", "273"], ["Hammer of Wrath", "39", "72"], ["Hammer of Light", "8", "34"], ["Melee hits", "362", "621"], ["Consecration", "188", "95"], ["Rebuke", "5", "15"], ["Hammer of Justice", "0", "4"], ["Blinding Light", "0", "3"], ["Guardian of Ancient Kings", "9", "4"]], "durations": [1224, null]}, {"kind": "pair", "title": "Kings' Rest +6 · 7 Oct", "sub": "Uptime: how much of the run each one was active", "cols": ["Dad", "Aquera"], "facts": [], "rows": [["Shield of the Righteous", "59%", "90%"], ["Avenger's Shield", "34%", "63%"], ["Consecration", "100%", "73%"]]}, {"kind": "pair", "title": "Kings' Rest +6 · 7 Oct", "sub": "Damage and self-healing: Dad vs Aquera", "cols": ["Dad", "Aquera"], "facts": [], "rows": [["Total damage", "45.22m", "120.54m"], ["Total healing", "21.01m", "31.12m"], ["Healing per second", "17,042", "25,270"], ["Sacrosanct Crusade", "7.04m", "11.96m"], ["Bulwark of Order", "3.12m", "6.46m"], ["Solace", "6.13m", "5.11m"], ["Word of Glory", "5 casts", "8 casts"], ["Lay on Hands", "0 casts", "1 cast"]]}], "working": ["Cast more: 38.5 casts per minute vs Aquera's 58 (Kings' Rest +6, 7 Oct)", "Shield of the Righteous: 154 casts vs 303", "Avenger's Shield: 44 casts vs 106"], "improved": ["No avoidable damage taken, held King Dazar for the whole last fight, and used defensives more than the top-ranked tank (Kings' Rest +6, 7 Oct)"]},
