S.mum={...S.arcane,base:"arcane",who:"Mum",img:"img/mum.jpg?v=2",eyebrow:"Mum · Ranged damage",chips:[["Sunfury hero tree","var(--accent)"]],logs:{"parses": [{"d": "Altar of Fangs +5", "p": 5, "info": "Damage · 83.52K DPS · 20:28 · parse 5 on character page (run page shows 4)", "date": "9 Oct"}], "best": {"p": 5, "sub": "Altar of Fangs +5 · 9 Oct"}, "highest": {"p": 5, "sub": "Altar of Fangs +5 · 9 Oct"}, "average": {"p": "5.0", "sub": "best parse in each dungeon, averaged · checked 9 Oct"}, "notesTitle": "What we learned", "notes": [{"date": "9 Oct", "items": ["Good job avoiding unnecessary damage: Mum took far less than Nmk (melee 1.19m vs 11.41m, Envenom 0.93m vs 3.16m).", "Casting more is the biggest gain. Dad, Sàm and Ràchel have had the same thing come up in their comparisons, so it's a whole-family thing to work on, not just Mum.", "Arcane Surge was cast 2 times vs Nmk's 11. Use it whenever it's ready.", "Arcane Blast is Mum's most-cast spell (148) but her lowest damage per cast (59.9K).", "Nmk's Arcane Orb and Arcane Phoenix hit much harder. Why isn't confirmed yet."]}], "comparisons": [{"kind": "pair", "title": "Altar of Fangs +5 · 9 Oct", "sub": "Damage: Mum vs Nmk", "cols": ["Mum", "Nmk"], "facts": [["Trinket", "Nmk's Fang of Umbral Malignance did 10.18m"]], "rows": [["DPS", "83,521", "225,911"], ["Arcane Missiles per cast", "254.7K", "396.5K"], ["Prismatic Bolt per cast", "579.5K", "783.7K"], ["Arcane Orb per cast", "192.7K", "804.2K"], ["Arcane Phoenix damage", "0.83m", "11.50m"]]}, {"kind": "pair", "title": "Altar of Fangs +5 · 9 Oct", "sub": "Casts: total (per minute), Mum vs Nmk", "cols": ["Mum", "Nmk"], "facts": [["Mum's total", "494 casts, 24.0 per minute"]], "rows": [["Arcane Barrage", "79 (3.8 per min)", "303 (14.7 per min)"], ["Arcane Missiles", "127 (6.2 per min)", "208 (10.1 per min)"], ["Arcane Blast", "148 (7.2 per min)", "37 (1.8 per min)"], ["Prismatic Bolt", "32 (1.6 per min)", "67 (3.3 per min)"], ["Arcane Orb", "31 (1.5 per min)", "30 (1.5 per min)"], ["Arcane Surge", "2 (0.1 per min)", "11 (0.5 per min)"], ["Touch of the Magi", "25 (1.2 per min)", "17 (0.8 per min)"], ["Prismatic Barrier", "19 (0.9 per min, up 29% of the run)", "39 (1.9 per min, up 43%)"]]}, {"kind": "pair", "title": "Altar of Fangs +5 · 9 Oct", "sub": "Damage taken (lower is better): Mum vs Nmk", "cols": ["Mum", "Nmk"], "facts": [], "rows": [["Melee", "1.19m", "11.41m"], ["Envenom", "0.93m", "3.16m"], ["Refraction", "2.29m", "2.83m"]]}], "working": ["Cast more: 24 casts per minute (Altar of Fangs +5, 9 Oct)", "Use Arcane Surge whenever it's ready: 2 casts vs Nmk's 11", "Arcane Blast is her most-cast spell but lowest damage per cast (59.9K)"], "improved": ["Took far less damage than Nmk: melee 1.19m vs 11.41m, Envenom 0.93m vs 3.16m (Altar of Fangs +5, 9 Oct)"]}};
